// @FIGURE_CODE_BEGIN
var container = document.getElementById('container');
var canvas = document.createElement('canvas');
canvas.style.width = '100%';
canvas.style.height = '100%';
canvas.style.display = 'block';
container.appendChild(canvas);

var MAGENTA = '#ec008c';
var state = {
  wavelength: 217,
  focus: 'Peak-only',
  step: 0
};

function absorbanceAt(x) {
  var sigma = x < 215 ? 11.0 : 9.0;
  var peak = 0.81 * Math.exp(-0.5 * Math.pow((x - 215) / sigma, 2));
  var tail = x <= 220 ? 0.070 : 0.070 * Math.exp(-(x - 220) / 145) + 0.002;
  return Math.max(0, peak + tail);
}

function buildSpectrumData() {
  var pts = [];
  for (var x = 200; x <= 400; x += 1) {
    pts.push({ x: x, y: absorbanceAt(x) });
  }
  return pts;
}

function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

function roundedRect(ctx, x, y, w, h, r) {
  var rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.lineTo(x + w - rr, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
  ctx.lineTo(x + w, y + h - rr);
  ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
  ctx.lineTo(x + rr, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
  ctx.lineTo(x, y + rr);
  ctx.quadraticCurveTo(x, y, x + rr, y);
  ctx.closePath();
}

var uvTeachingPlugin = {
  id: 'uvTeachingPlugin',
  beforeUpdate: function (chart) {
    var m = Math.max(260, Math.min(chart.width || 900, chart.height || 520));
    var tickSize = clamp(m * 0.030, 10, 16);
    var titleSize = clamp(m * 0.038, 13, 18);
    chart.options.scales.x.ticks.font = { family: 'Georgia, Times New Roman, serif', size: tickSize };
    chart.options.scales.y.ticks.font = { family: 'Georgia, Times New Roman, serif', size: tickSize };
    chart.options.scales.x.title.font = { family: 'Arial, Helvetica, sans-serif', size: titleSize, weight: 'normal' };
    chart.options.scales.y.title.font = { family: 'Arial, Helvetica, sans-serif', size: titleSize, weight: 'normal' };
  },
  beforeDraw: function (chart) {
    var ctx = chart.ctx;
    var a = chart.chartArea;
    if (!a) return;
    ctx.save();
    var grad = ctx.createLinearGradient(0, a.top, 0, a.bottom);
    grad.addColorStop(0, '#f4d9e2');
    grad.addColorStop(0.55, '#fbf0f3');
    grad.addColorStop(1, '#ffffff');
    ctx.fillStyle = grad;
    ctx.fillRect(a.left, a.top, a.right - a.left, a.bottom - a.top);
    ctx.restore();
  },
  beforeDatasetsDraw: function (chart) {
    var ctx = chart.ctx;
    var a = chart.chartArea;
    var xs = chart.scales.x;
    if (!a || !xs) return;

    ctx.save();

    if (state.focus === 'Peak-only') {
      var p1 = xs.getPixelForValue(211);
      var p2 = xs.getPixelForValue(223);
      ctx.fillStyle = 'rgba(236, 0, 140, 0.105)';
      ctx.fillRect(p1, a.top, p2 - p1, a.bottom - a.top);

      var t = xs.getPixelForValue(250);
      ctx.fillStyle = 'rgba(255, 255, 255, 0.34)';
      ctx.fillRect(t, a.top, a.right - t, a.bottom - a.top);
    } else {
      var tx = xs.getPixelForValue(250);
      ctx.fillStyle = 'rgba(236, 0, 140, 0.060)';
      ctx.fillRect(tx, a.top, a.right - tx, a.bottom - a.top);
    }

    ctx.restore();
  },
  afterDatasetsDraw: function (chart) {
    var ctx = chart.ctx;
    var a = chart.chartArea;
    var xs = chart.scales.x;
    var ys = chart.scales.y;
    if (!a || !xs || !ys) return;

    var minDim = Math.max(220, Math.min(a.right - a.left, a.bottom - a.top));
    var markerR = clamp(minDim * 0.012, 3.2, 6.2);
    var lineW = clamp(minDim * 0.006, 1.5, 2.8);
    var labelFont = clamp(minDim * 0.040, 12, 19);
    var readoutFont = clamp(minDim * 0.028, 10, 13);

    ctx.save();

    var peakX = 217;
    var peakY = absorbanceAt(peakX);
    var peakPx = xs.getPixelForValue(peakX);
    var peakPy = ys.getPixelForValue(peakY);

    ctx.font = labelFont + 'px Georgia, Times New Roman, serif';
    ctx.textBaseline = 'middle';
    ctx.textAlign = 'left';
    ctx.fillStyle = '#111111';
    ctx.strokeStyle = 'rgba(255,255,255,0.86)';
    ctx.lineWidth = 4;
    ctx.lineJoin = 'round';
    var annoX = clamp(peakPx + minDim * 0.055, a.left + 8, a.right - minDim * 0.30);
    var annoY = clamp(peakPy - minDim * 0.015, a.top + 18, a.bottom - 18);
    ctx.strokeText('λmax = 217 nm', annoX, annoY);
    ctx.fillText('λmax = 217 nm', annoX, annoY);

    var mx = xs.getPixelForValue(state.wavelength);
    var my = ys.getPixelForValue(absorbanceAt(state.wavelength));

    ctx.beginPath();
    ctx.arc(mx, my, markerR + 2, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(255,255,255,0.95)';
    ctx.fill();

    ctx.beginPath();
    ctx.arc(mx, my, markerR, 0, Math.PI * 2);
    ctx.fillStyle = '#ffffff';
    ctx.fill();
    ctx.lineWidth = lineW;
    ctx.strokeStyle = MAGENTA;
    ctx.stroke();

    var txt = 'λ = ' + Math.round(state.wavelength) + ' nm, A ≈ ' + absorbanceAt(state.wavelength).toFixed(2);
    ctx.font = readoutFont + 'px Arial, Helvetica, sans-serif';
    var pad = Math.max(4, readoutFont * 0.45);
    var tw = ctx.measureText(txt).width;
    var boxW = tw + 2 * pad;
    var boxH = readoutFont + 2 * pad;
    var bx = mx + markerR + 8;
    var by = my + markerR + 8;

    if (bx + boxW > a.right - 2) bx = mx - markerR - 8 - boxW;
    if (by + boxH > a.bottom - 2) by = my - markerR - 8 - boxH;
    bx = clamp(bx, a.left + 2, a.right - boxW - 2);
    by = clamp(by, a.top + 2, a.bottom - boxH - 2);

    ctx.fillStyle = 'rgba(255,255,255,0.90)';
    ctx.strokeStyle = 'rgba(236,0,140,0.45)';
    ctx.lineWidth = 1;
    roundedRect(ctx, bx, by, boxW, boxH, 4);
    ctx.fill();
    ctx.stroke();

    ctx.fillStyle = '#111111';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(txt, bx + pad, by + boxH / 2);

    ctx.restore();
  },
  afterDraw: function (chart) {
    var ctx = chart.ctx;
    var a = chart.chartArea;
    if (!a) return;

    var minDim = Math.max(220, Math.min(a.right - a.left, a.bottom - a.top));
    var arrowW = clamp(minDim * 0.006, 1.5, 3);
    var head = clamp(minDim * 0.018, 5, 9);

    ctx.save();
    ctx.strokeStyle = MAGENTA;
    ctx.fillStyle = MAGENTA;
    ctx.lineWidth = arrowW;
    ctx.lineCap = 'butt';

    var xLabelY = chart.height - clamp(minDim * 0.030, 12, 18);
    var x0 = (a.left + a.right) / 2 + clamp(minDim * 0.17, 54, 100);
    var x1 = x0 + clamp(minDim * 0.13, 38, 70);
    if (x1 < chart.width - 8) {
      ctx.beginPath();
      ctx.moveTo(x0, xLabelY);
      ctx.lineTo(x1, xLabelY);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(x1, xLabelY);
      ctx.lineTo(x1 - head, xLabelY - head * 0.48);
      ctx.lineTo(x1 - head, xLabelY + head * 0.48);
      ctx.closePath();
      ctx.fill();
    }

    var yArrowX = clamp(a.left - clamp(minDim * 0.105, 36, 62), 8, a.left - 16);
    var y0 = (a.top + a.bottom) / 2 + clamp(minDim * 0.17, 45, 75);
    var y1 = y0 - clamp(minDim * 0.30, 72, 120);
    if (yArrowX > 2) {
      ctx.beginPath();
      ctx.moveTo(yArrowX, y0);
      ctx.lineTo(yArrowX, y1);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(yArrowX, y1);
      ctx.lineTo(yArrowX - head * 0.48, y1 + head);
      ctx.lineTo(yArrowX + head * 0.48, y1 + head);
      ctx.closePath();
      ctx.fill();
    }

    ctx.restore();
  }
};

var chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
  data: {
    datasets: [{
      data: buildSpectrumData(),
      parsing: false,
      borderColor: MAGENTA,
      segment: {
        borderColor: function (ctx) {
          if (state.focus === 'Peak-only' && ctx.p0.parsed.x >= 250) return 'rgba(236,0,140,0.42)';
          return MAGENTA;
        }
      },
      borderWidth: function (ctx) {
        var area = ctx.chart.chartArea;
        if (!area) return 2.4;
        var m = Math.min(area.right - area.left, area.bottom - area.top);
        return clamp(m * 0.0065, 1.8, 3.0);
      },
      pointRadius: 0,
