    },
    layout: {
      padding: { left: 22, right: 12, top: 8, bottom: 8 }
    },
    scales: {
      x: {
        type: 'linear',
        min: 200,
        max: 400,
        grid: {
          drawOnChartArea: false,
          drawTicks: true,
          tickLength: 12,
          color: '#000000'
        },
        border: { display: true, color: '#000000', width: 1.2 },
        ticks: {
          color: '#000000',
          stepSize: 20,
          callback: function (v) { return String(Math.round(v)); }
        },
        title: {
          display: true,
          text: 'Wavelength (nm)',
          color: '#000000',
          padding: { top: 8 }
        }
      },
      y: {
        min: 0,
        max: 1.0,
        grid: {
          drawOnChartArea: false,
          drawTicks: true,
          tickLength: 12,
          color: '#000000'
        },
        border: { display: true, color: '#000000', width: 1.2 },
        ticks: {
          color: '#000000',
          stepSize: 0.2,
          callback: function (v) {
            if (Math.abs(v) < 1e-9) return '0';
