});
window.__markRendered();

function refreshChart() {
  chart.update('none');
}

function update_wavelengthScan(v) {
  state.wavelength = clamp(v, 200, 400);
  var out = document.getElementById('wavelengthScanVal');
  if (out) out.value = String(Math.round(state.wavelength));
  var input = document.getElementById('wavelengthScanInput');
  if (input && +input.value !== state.wavelength) input.value = String(Math.round(state.wavelength));
