}

function toggle_viewFocus(on) {
  state.focus = on ? 'Full-tail' : 'Peak-only';
  var val = document.getElementById('viewFocusVal');
  if (val) val.textContent = state.focus;
  var cb = document.getElementById('viewFocusInput');
  if (cb) cb.checked = !!on;
  refreshChart();
}

var demoSteps = [
  {
    title: 'Find the maximum',
    narration: 'Start with the marker at the crest of the magenta curve. The absorbance readout is highest near 217 nm, so this wavelength is labeled λmax.',
    state: { wavelengthScan: 217, viewFocus: 'Peak-only' }
  },
  {
    title: 'Scan away from the crest',
    narration: 'Move the wavelength slider to the right and watch the dot drop rapidly down the curve. The absorbance falls sharply after the maximum, showing why nearby wavelengths are not λmax.',
    state: { wavelengthScan: 240, viewFocus: 'Peak-only' }
  },
  {
    title: 'Compare the long tail',
    narration: 'Switch to the full-tail view and scan through longer wavelengths. Beyond about 250 nm, the curve is nearly flat and close to the baseline, so the diagnostic absorption is the short-wavelength peak rather than the tail.',
    state: { wavelengthScan: 320, viewFocus: 'Full-tail' }
  }
];

function applyStep(i) {
  state.step = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[state.step];

  var narration = document.getElementById('demoNarration');
  if (narration) narration.textContent = step.narration;

  var label = document.getElementById('stepLabel');
  if (label) label.textContent = (state.step + 1) + '/' + demoSteps.length + ' ' + step.title;

  if (step.state.wavelengthScan != null) {
    update_wavelengthScan(+step.state.wavelengthScan);
  }
  if (step.state.viewFocus != null) {
    toggle_viewFocus(step.state.viewFocus === 'Full-tail');
  }
}

function prevStep() {
  applyStep(state.step - 1);
}

function nextStep() {
  applyStep(state.step + 1);
}

window.update_wavelengthScan = update_wavelengthScan;
window.toggle_viewFocus = toggle_viewFocus;
window.prevStep = prevStep;
window.nextStep = nextStep;

canvas.addEventListener('mousemove', function (event) {
  var area = chart.chartArea;
  if (!area) return;
  var rect = canvas.getBoundingClientRect();
  var px = event.clientX - rect.left;
  var py = event.clientY - rect.top;
  var mx = chart.scales.x.getPixelForValue(state.wavelength);
  var my = chart.scales.y.getPixelForValue(absorbanceAt(state.wavelength));
  var d = Math.hypot(px - mx, py - my);
  if (d < 18) {
    canvas.style.cursor = 'pointer';
    showTooltip('Marker readout: λ = ' + Math.round(state.wavelength) + ' nm, absorbance ≈ ' + absorbanceAt(state.wavelength).toFixed(2) + '.', event);
  } else if (px >= area.left && px <= area.right && py >= area.top && py <= area.bottom) {
    var xVal = chart.scales.x.getValueForPixel(px);
    canvas.style.cursor = 'crosshair';
    showTooltip('Scanning the spectrum here gives λ ≈ ' + Math.round(xVal) + ' nm and A ≈ ' + absorbanceAt(xVal).toFixed(2) + '.', event);
  } else {
    canvas.style.cursor = '';
    hideTooltip();
  }
});

canvas.addEventListener('mouseleave', function () {
  canvas.style.cursor = '';
  hideTooltip();
});

canvas.addEventListener('click', function (event) {
  var rect = canvas.getBoundingClientRect();
  var px = event.clientX - rect.left;
  var xVal = chart.scales.x.getValueForPixel(px);
  if (xVal >= 200 && xVal <= 400) {
    update_wavelengthScan(Math.round(xVal));
    showPopup('Reading λmax', 'The diagnostic λmax is the wavelength where absorbance is greatest. For this 1,3-butadiene spectrum, the peak occurs near 217 nm; the much longer-wavelength tail has only weak absorbance.');
  }
});

applyStep(0);
// @FIGURE_CODE_END

