  [252, 0.070], [265, 0.063], [285, 0.055], [305, 0.048],
  [325, 0.041], [345, 0.035], [365, 0.030], [385, 0.026],
  [400, 0.023]
];

function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

function absorbanceAt(x) {
  x = clamp(x, 200, 400);
  for (var i = 0; i < anchors.length - 1; i++) {
    var p1 = anchors[i], p2 = anchors[i + 1];
    if (x >= p1[0] && x <= p2[0]) {
      var p0 = anchors[Math.max(0, i - 1)];
      var p3 = anchors[Math.min(anchors.length - 1, i + 2)];
      var dx = p2[0] - p1[0];
      var t = (x - p1[0]) / dx;
      var t2 = t * t, t3 = t2 * t;
      var m1 = (p2[1] - p0[1]) / (p2[0] - p0[0]);
      var m2 = (p3[1] - p1[1]) / (p3[0] - p1[0]);
      var y =
        (2 * t3 - 3 * t2 + 1) * p1[1] +
        (t3 - 2 * t2 + t) * dx * m1 +
        (-2 * t3 + 3 * t2) * p2[1] +
        (t3 - t2) * dx * m2;
      return clamp(y, 0, 0.95);
    }
  }
  return anchors[anchors.length - 1][1];
}

function roundedRect(ctx, x, y, w, h, r) {
  var rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.lineTo(x + w - rr, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
  ctx.lineTo(x + w, y + h - rr);
  ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
  ctx.lineTo(x + rr, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
  ctx.lineTo(x, y + rr);
  ctx.quadraticCurveTo(x, y, x + rr, y);
  ctx.closePath();
}

function arrow(ctx, x0, y0, x1, y1, head, color, lw) {
  var ang = Math.atan2(y1 - y0, x1 - x0);
  ctx.save();
  ctx.strokeStyle = color;
  ctx.fillStyle = color;
  ctx.lineWidth = lw;
  ctx.lineCap = 'butt';
  ctx.beginPath();
  ctx.moveTo(x0, y0);
  ctx.lineTo(x1, y1);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - head * Math.cos(ang - Math.PI / 6), y1 - head * Math.sin(ang - Math.PI / 6));
  ctx.lineTo(x1 - head * Math.cos(ang + Math.PI / 6), y1 - head * Math.sin(ang + Math.PI / 6));
  ctx.closePath();
  ctx.fill();
  ctx.restore();
}

function getFrame(chart) {
  var w = chart.width;
  var h = chart.height;
  var s = Math.min(w, h);
  var tickFont = clamp(s * 0.040, 12, 22);
  var axisFont = clamp(s * 0.041, 13, 22);
  var left = clamp(w * 0.088, 54, 100);
  var rightPad = clamp(w * 0.020, 10, 28);
  var topMin = clamp(h * 0.020, 8, 16);
  var tickSpace = tickFont * 1.75;
  var xTitleSpace = axisFont * 2.15;
  var bottomPad = tickSpace + xTitleSpace + clamp(h * 0.006, 2, 6);
  var availableW = Math.max(80, w - left - rightPad);
  var availableH = Math.max(80, h - topMin - bottomPad);
  var targetAspect = 2.47;
  var plotW = availableW;
  var plotH = Math.min(availableH, plotW / targetAspect);
  if (plotH < availableH * 0.52 && availableH < plotW / targetAspect) plotH = availableH;
  plotW = Math.min(availableW, plotH * targetAspect);
  var left2 = left + Math.max(0, (availableW - plotW) * 0.18);
  var top = topMin + Math.max(0, (availableH - plotH) * 0.22);
  return {
    left: left2,
    right: left2 + plotW,
    top: top,
    bottom: top + plotH,
    width: plotW,
    height: plotH,
    tickFont: tickFont,
    axisFont: axisFont,
    lineW: clamp(Math.min(plotW, plotH) * 0.008, 1.25, 2.4),
    tickLen: clamp(Math.min(plotW, plotH) * 0.032, 7, 12)
  };
}

function xPix(f, x) {
  return f.left + (x - 200) / 200 * f.width;
}

function yPix(f, y) {
  return f.bottom - y * f.height;
}

function valueFromX(f, px) {
  return 200 + (px - f.left) / f.width * 200;
}

function drawLambdaMaxLabel(ctx, x, y, size) {
  ctx.save();
  ctx.fillStyle = BLACK;
  ctx.textBaseline = 'alphabetic';
  ctx.textAlign = 'left';
  ctx.font = size + 'px Georgia, Times New Roman, serif';
  ctx.fillText('λ', x, y);
  var x2 = x + ctx.measureText('λ').width + size * 0.01;
  ctx.font = Math.round(size * 0.64) + 'px Georgia, Times New Roman, serif';
  ctx.fillText('max', x2, y + size * 0.20);
  x2 += ctx.measureText('max').width + size * 0.28;
  ctx.font = size + 'px Georgia, Times New Roman, serif';
  ctx.fillText('= 217 nm', x2, y);
  ctx.restore();
}

function drawCurve(ctx, f, tailFaded) {
  ctx.save();
  ctx.beginPath();
  for (var x = 200; x <= 400; x += 1) {
    var px = xPix(f, x);
    var py = yPix(f, absorbanceAt(x));
    if (x === 200) ctx.moveTo(px, py);
    else ctx.lineTo(px, py);
  }
  ctx.strokeStyle = tailFaded ? 'rgba(236,0,140,0.95)' : MAGENTA;
  ctx.lineWidth = f.lineW;
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  ctx.stroke();

  if (tailFaded) {
    ctx.globalCompositeOperation = 'source-over';
    ctx.beginPath();
    for (var xt = 250; xt <= 400; xt += 1) {
      var pxt = xPix(f, xt);
      var pyt = yPix(f, absorbanceAt(xt));
      if (xt === 250) ctx.moveTo(pxt, pyt);
      else ctx.lineTo(pxt, pyt);
    }
    ctx.strokeStyle = 'rgba(236,0,140,0.36)';
    ctx.lineWidth = f.lineW;
    ctx.stroke();
  }
  ctx.restore();
}

function drawTeachingOverlay(ctx, f) {
  if (!state.teachingVisible) return;
  ctx.save();
  ctx.beginPath();
  ctx.rect(f.left, f.top, f.width, f.height);
  ctx.clip();

  if (state.focus === 'Peak-only') {
    var a = xPix(f, 211.5), b = xPix(f, 222.5);
    ctx.fillStyle = 'rgba(236,0,140,0.075)';
    ctx.fillRect(a, f.top, b - a, f.height);
    var fadeX = xPix(f, 250);
    ctx.fillStyle = 'rgba(255,255,255,0.32)';
    ctx.fillRect(fadeX, f.top, f.right - fadeX, f.height);
  } else {
    var t = xPix(f, 250);
    ctx.fillStyle = 'rgba(236,0,140,0.055)';
    ctx.fillRect(t, f.top, f.right - t, f.height);
  }
  ctx.restore();
}

function drawMarker(ctx, f) {
  if (!state.teachingVisible) return;

  var minDim = Math.min(f.width, f.height);
  var r = clamp(minDim * 0.018, 3.0, 5.5);
  var font = clamp(minDim * 0.052, 10, 14);
  var x = clamp(state.wavelength, 200, 400);
  var y = absorbanceAt(x);
  var px = xPix(f, x);
  var py = yPix(f, y);

  ctx.save();

  ctx.beginPath();
  ctx.arc(px, py, r + 1.8, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(255,255,255,0.96)';
  ctx.fill();

  ctx.beginPath();
  ctx.arc(px, py, r, 0, Math.PI * 2);
  ctx.fillStyle = '#ffffff';
  ctx.fill();
  ctx.strokeStyle = MAGENTA;
  ctx.lineWidth = clamp(minDim * 0.008, 1.5, 2.4);
  ctx.stroke();

  var txt = 'λ = ' + Math.round(x) + ' nm, A ≈ ' + y.toFixed(2);
  ctx.font = font + 'px Arial, Helvetica, sans-serif';
  var pad = clamp(font * 0.48, 4, 7);
  var tw = ctx.measureText(txt).width;
  var bw = tw + pad * 2;
  var bh = font + pad * 2;
  var bx = px + r + pad * 1.4;
  var by = py + r + pad * 1.1;
  if (bx + bw > f.right - 2) bx = px - r - pad * 1.4 - bw;
  if (by + bh > f.bottom - 2) by = py - r - pad * 1.1 - bh;
  bx = clamp(bx, f.left + 2, f.right - bw - 2);
  by = clamp(by, f.top + 2, f.bottom - bh - 2);

  roundedRect(ctx, bx, by, bw, bh, clamp(pad * 0.75, 3, 5));
  ctx.fillStyle = 'rgba(255,255,255,0.92)';
  ctx.fill();
  ctx.strokeStyle = 'rgba(236,0,140,0.42)';
  ctx.lineWidth = 1;
  ctx.stroke();

  ctx.fillStyle = BLACK;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText(txt, bx + pad, by + bh / 2);

  ctx.restore();
}

var uvSpectrumPlugin = {
  id: 'uvSpectrumPlugin',
  afterDraw: function (chart) {
    var ctx = chart.ctx;
    var f = getFrame(chart);
    var minDim = Math.min(f.width, f.height);

    ctx.save();
    ctx.clearRect(0, 0, chart.width, chart.height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, chart.width, chart.height);

    var grad = ctx.createLinearGradient(0, f.top, 0, f.bottom);
    grad.addColorStop(0, '#f2d8df');
    grad.addColorStop(0.52, '#fbf0f3');
    grad.addColorStop(1, '#ffffff');
    ctx.fillStyle = grad;
    ctx.fillRect(f.left, f.top, f.width, f.height);

    drawTeachingOverlay(ctx, f);

    ctx.save();
    ctx.beginPath();
    ctx.rect(f.left, f.top, f.width, f.height);
    ctx.clip();
    drawCurve(ctx, f, state.teachingVisible && state.focus === 'Peak-only');
    ctx.restore();

    ctx.strokeStyle = BLACK;
    ctx.lineWidth = clamp(minDim * 0.005, 1, 1.5);
    ctx.strokeRect(f.left, f.top, f.width, f.height);

    ctx.strokeStyle = BLACK;
    ctx.fillStyle = BLACK;
    ctx.lineWidth = clamp(minDim * 0.004, 1, 1.4);

    ctx.font = f.tickFont + 'px Georgia, Times New Roman, serif';
    ctx.textBaseline = 'top';
    ctx.textAlign = 'center';
    for (var xv = 200; xv <= 400; xv += 20) {
      var xp = xPix(f, xv);
      ctx.beginPath();
      ctx.moveTo(xp, f.bottom);
      ctx.lineTo(xp, f.bottom + f.tickLen);
      ctx.stroke();
      ctx.fillText(String(xv), xp, f.bottom + f.tickLen + f.tickFont * 0.38);
    }

    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    for (var yv = 0; yv <= 1.0001; yv += 0.2) {
      var yp = yPix(f, yv);
      ctx.beginPath();
      ctx.moveTo(f.left, yp);
      ctx.lineTo(f.left - f.tickLen, yp);
      ctx.stroke();
      var lab = Math.abs(yv) < 1e-9 ? '0' : yv.toFixed(1);
      ctx.fillText(lab, f.left - f.tickLen - f.tickFont * 0.45, yp);
    }

    ctx.font = f.axisFont + 'px Arial, Helvetica, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'alphabetic';
    var xLabelY = f.bottom + f.tickLen + f.tickFont * 1.82 + f.axisFont;
    ctx.fillText('Wavelength (nm)', (f.left + f.right) / 2, xLabelY);

    ctx.save();
    ctx.translate(f.left - f.tickLen - f.tickFont * 2.8 - f.axisFont * 1.15, (f.top + f.bottom) / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('Absorbance', 0, 0);
    ctx.restore();

    var head = clamp(minDim * 0.026, 5, 10);
    var lw = clamp(minDim * 0.009, 1.8, 3.0);
    var xLabelWidth = ctx.measureText('Wavelength (nm)').width;
    var ax0 = (f.left + f.right) / 2 + xLabelWidth / 2 + f.axisFont * 0.85;
    var ax1 = Math.min(f.right - f.width * 0.28, ax0 + f.width * 0.13);
    if (ax1 > ax0 + head * 2) arrow(ctx, ax0, xLabelY - f.axisFont * 0.30, ax1, xLabelY - f.axisFont * 0.30, head, MAGENTA, lw);

    var yArrowX = Math.max(5, f.left - f.tickLen - f.tickFont * 2.8 - f.axisFont * 2.25);
    arrow(ctx, yArrowX, f.top + f.height * 0.46, yArrowX, f.top + f.height * 0.15, head, MAGENTA, lw);

    var labelSize = clamp(minDim * 0.065, 14, 23);
    var peakX = xPix(f, 217);
    var peakY = yPix(f, absorbanceAt(217));
    drawLambdaMaxLabel(ctx, peakX + f.width * 0.035, peakY - labelSize * 0.10, labelSize);

    drawMarker(ctx, f);

    chart.$uvFrame = f;
    ctx.restore();
  }
};

var chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
  data: { datasets: [] },
