window.__markRendered();

function refreshChart() {
  chart.draw();
}

function revealTeaching() {
  state.teachingVisible = true;
}

function update_wavelengthScan(v) {
  revealTeaching();
  state.wavelength = clamp(v, 200, 400);
  var rounded = Math.round(state.wavelength);
  var out = document.getElementById('wavelengthScanVal');
  if (out) out.value = String(rounded);
  var input = document.getElementById('wavelengthScanInput');
  if (input && +input.value !== rounded) input.value = String(rounded);
  refreshChart();
}

function toggle_viewFocus(on) {
  revealTeaching();
  state.focus = on ? 'Full-tail' : 'Peak-only';
  var val = document.getElementById('viewFocusVal');
  if (val) val.textContent = state.focus;
  var cb = document.getElementById('viewFocusInput');
  if (cb) cb.checked = !!on;
  refreshChart();
}

var demoSteps = [
  {
    title: 'Find the maximum',
    narration: 'Start with the marker at the crest of the magenta curve. The absorbance readout is highest near 217 nm, so this wavelength is labeled λmax.',
    state: { wavelengthScan: 217, viewFocus: 'Peak-only' }
  },
  {
    title: 'Scan away from the crest',
    narration: 'Move the wavelength slider to the right and watch the dot drop rapidly down the curve. The absorbance falls sharply after the maximum, showing why nearby wavelengths are not λmax.',
    state: { wavelengthScan: 240, viewFocus: 'Peak-only' }
  },
  {
    title: 'Compare the long tail',
    narration: 'Switch to the full-tail view and scan through longer wavelengths. Beyond about 250 nm, the curve is nearly flat and close to the baseline, so the diagnostic absorption is the short-wavelength peak rather than the tail.',
    state: { wavelengthScan: 320, viewFocus: 'Full-tail' }
  }
];

function setStepText(i) {
  var step = demoSteps[i];
  var narration = document.getElementById('demoNarration');
  if (narration) narration.textContent = step.narration;
  var label = document.getElementById('stepLabel');
  if (label) label.textContent = (i + 1) + '/' + demoSteps.length + ' ' + step.title;
}

function applyStep(i) {
  state.step = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[state.step];
  setStepText(state.step);
  revealTeaching();

  if (step.state.wavelengthScan != null) {
    state.wavelength = clamp(+step.state.wavelengthScan, 200, 400);
    var out = document.getElementById('wavelengthScanVal');
    if (out) out.value = String(Math.round(state.wavelength));
    var inp = document.getElementById('wavelengthScanInput');
    if (inp) inp.value = String(Math.round(state.wavelength));
  }

  if (step.state.viewFocus != null) {
    state.focus = step.state.viewFocus;
    var cb = document.getElementById('viewFocusInput');
    if (cb) cb.checked = state.focus === 'Full-tail';
    var val = document.getElementById('viewFocusVal');
    if (val) val.textContent = state.focus;
  }

  refreshChart();
}

function prevStep() {
  applyStep(state.step - 1);
}

function nextStep() {
  applyStep(state.step + 1);
}

window.update_wavelengthScan = update_wavelengthScan;
window.toggle_viewFocus = toggle_viewFocus;
window.prevStep = prevStep;
window.nextStep = nextStep;

setStepText(0);

canvas.addEventListener('mousemove', function (event) {
  var rect = canvas.getBoundingClientRect();
  var px = (event.clientX - rect.left) * (chart.width / rect.width);
  var py = (event.clientY - rect.top) * (chart.height / rect.height);
  var f = chart.$uvFrame || getFrame(chart);

  if (px >= f.left && px <= f.right && py >= f.top && py <= f.bottom) {
    var xVal = clamp(valueFromX(f, px), 200, 400);
    var cy = yPix(f, absorbanceAt(xVal));
    var dist = Math.abs(py - cy);
    canvas.style.cursor = dist < 14 || state.teachingVisible ? 'pointer' : 'crosshair';
    if (state.teachingVisible && Math.hypot(px - xPix(f, state.wavelength), py - yPix(f, absorbanceAt(state.wavelength))) < 18) {
      showTooltip('Marker readout: λ = ' + Math.round(state.wavelength) + ' nm, absorbance ≈ ' + absorbanceAt(state.wavelength).toFixed(2) + '.', event);
    } else {
      showTooltip('At λ ≈ ' + Math.round(xVal) + ' nm, A ≈ ' + absorbanceAt(xVal).toFixed(2) + '. The maximum occurs near 217 nm.', event);
    }
  } else {
    canvas.style.cursor = '';
    hideTooltip();
  }
});

canvas.addEventListener('mouseleave', function () {
  canvas.style.cursor = '';
  hideTooltip();
});

canvas.addEventListener('click', function (event) {
  var rect = canvas.getBoundingClientRect();
  var px = (event.clientX - rect.left) * (chart.width / rect.width);
  var f = chart.$uvFrame || getFrame(chart);
  if (px >= f.left && px <= f.right) {
    var xVal = Math.round(clamp(valueFromX(f, px), 200, 400));
    update_wavelengthScan(xVal);
    showPopup('Reading λmax', 'λmax is the wavelength where the absorbance reaches its highest value. In this spectrum of 1,3-butadiene, the peak is near 217 nm; the long-wavelength tail is much weaker and is not the diagnostic maximum.');
  }
});
